import os
import re
from collections import defaultdict

# 深度检查 1: 扫描所有 .h 中的 private 成员变量，并在对应的 .cpp 和 .h 中查找其引用次数
headers = []
sources = []
for root, _, files in os.walk("src"):
    for f in files:
        full = os.path.join(root, f)
        if f.endswith(".h"):
            headers.append(full)
        elif f.endswith(".cpp"):
            sources.append(full)

all_code = {}
for p in headers + sources:
    with open(p, "r", encoding="utf-8", errors="ignore") as f:
        all_code[p] = f.read()

# 检查 1: 匿名命名空间中的 static / 自由函数定义，检查是否在同文件中被调用
dead_internal_funcs = []
for p, content in all_code.items():
    if p.endswith(".cpp"):
        # 找 static 返回类型 函数名( 或 匿名命名空间中的函数
        # 简单匹配: static [a-zA-Z0-9_<>&*:]+ ([a-zA-Z0-9_]+)\(
        matches = re.finditer(r'\bstatic\s+[a-zA-Z0-9_<>:*&]+\s+([a-zA-Z0-9_]+)\s*\(', content)
        for m in matches:
            fn_name = m.group(1)
            # 在该文件中出现的次数（排除自身定义处）
            occurrences = len(re.findall(r'\b' + re.escape(fn_name) + r'\b', content))
            if occurrences <= 1:
                # 只有定义处，没有调用处！
                dead_internal_funcs.append((p, fn_name, "可能未被调用的 static 函数"))

# 检查 2: 未使用的 private 成员变量 (以 _ 结尾或 m_ 开头或普通声明)
dead_private_members = []
for h_path in headers:
    h_content = all_code[h_path]
    # 找对应的 .cpp
    cpp_path = h_path[:-2] + ".cpp"
    combined_code = h_content + "\n" + all_code.get(cpp_path, "")

    # 提取 private: 块
    private_blocks = re.findall(r'private:\s*(.*?)(?:public:|protected:|};)', h_content, re.DOTALL)
    for block in private_blocks:
        # 提取变量声明, 例如: int foo_; std::string bar_; bool active_ = false;
        var_matches = re.finditer(r'([a-zA-Z0-9_<>&*:]+)\s+([a-zA-Z0-9_]+(?:_[a-zA-Z0-9_]*|_[0-9]*|_)?)\s*(?:=\s*[^;]+)?\s*;', block)
        for vm in var_matches:
            vname = vm.group(2)
            # 过滤掉方法声明（包含括号的）和已知类型名
            if '(' in vname or ')' in vname:
                continue
            # 检查在 h_content + cpp_content 中的出现次数
            count = len(re.findall(r'\b' + re.escape(vname) + r'\b', combined_code))
            if count <= 1:
                dead_private_members.append((h_path, vname, "定义了但从未在类实现中读写的 private 成员"))

# 检查 3: 冗余的 return; 在 void 函数末尾
redundant_void_returns = []
for p, content in all_code.items():
    # 匹配 }\s*return;\s*}
    lines = content.splitlines()
    for i in range(len(lines) - 1):
        if re.match(r'^\s*return\s*;\s*$', lines[i]) and re.match(r'^\s*}\s*$', lines[i+1]):
            # 前一行如果不是 if/else/case 等控制流分支，可能属于函数末尾的冗余 return
            if i > 0 and not re.search(r'\b(if|else|case|default|while|for)\b', lines[i-1]):
                redundant_void_returns.append((p, i+1, lines[i].strip()))

print("=== 深度死代码/冗余检测结果 ===")
print(f"\n[1] 未引用的 static 函数 (只定义未调用): {len(dead_internal_funcs)} 处")
for p, fn, desc in dead_internal_funcs:
    print(f"  {p}: {fn} ({desc})")

print(f"\n[2] 未使用的 private 成员变量 (只声明未读写): {len(dead_private_members)} 处")
for p, v, desc in dead_private_members:
    print(f"  {p}: {v} ({desc})")

print(f"\n[3] 函数末尾冗余的 return;: {len(redundant_void_returns)} 处")
for p, line_no, code in redundant_void_returns:
    print(f"  {p}:{line_no}: {code}")
EOF

