import os
import re
from collections import defaultdict

src_files = []
for root, _, files in os.walk("src"):
    for f in files:
        if f.endswith((".cpp", ".h")):
            src_files.append(os.path.join(root, f))

# 检查 1: 扫描每个类里声明的 private 方法，并在全项目中搜索是否有任何地方调用了它！
class_private_methods = []
for p in src_files:
    if p.endswith(".h"):
        with open(p, "r", encoding="utf-8", errors="ignore") as f:
            content = f.read()

        # 寻找 private 区域
        private_blocks = re.findall(r'private:\s*(.*?)(?:public:|protected:|};)', content, re.DOTALL)
        for block in private_blocks:
            # 匹配函数声明：void Foo(); 或 bool Bar(int a, const std::string& b);
            method_matches = re.finditer(r'(?:virtual\s+)?([a-zA-Z0-9_<>&*:]+)\s+([A-Z][a-zA-Z0-9_]*|[a-z][a-zA-Z0-9_]*)\s*\(([^)]*)\)\s*(?:const)?\s*(?:override)?\s*;', block)
            for mm in method_matches:
                mname = mm.group(2)
                # 排除构造函数、析构函数、Q_OBJECT 宏等
                if mname in ["Q_OBJECT", "Q_DISABLE_COPY", "override", "virtual"] or mname.startswith("~"):
                    continue
                # 记录下来去全库搜
                class_private_methods.append((p, mname))

# 在所有 cpp/h 中统计这些 private 方法被使用的次数
dead_methods = []
for header_path, mname in class_private_methods:
    total_refs = 0
    ref_locations = []
    for p in src_files:
        with open(p, "r", encoding="utf-8", errors="ignore") as f:
            c = f.read()
        matches = list(re.finditer(r'\b' + re.escape(mname) + r'\b', c))
        if matches:
            total_refs += len(matches)
            ref_locations.append((p, len(matches)))

    # 如果总共只出现 1 次（只有头文件声明，没有实现，也没有调用），或者只出现 2 次（1次声明 + 1次实现，但没有任何调用点）
    # 仔细检查是不是只有定义没有调用
    if total_refs == 1:
        dead_methods.append((header_path, mname, "在头文件声明了但从未实现也从未调用 (纯死声明)"))
    elif total_refs == 2:
        # 看看是不是一次在 .h，一次在 .cpp 定义
        cpp_match = False
        for p, count in ref_locations:
            if p.endswith(".cpp"):
                with open(p, "r", encoding="utf-8", errors="ignore") as f:
                    lines = f.readlines()
                for l in lines:
                    if re.search(r'::' + re.escape(mname) + r'\s*\(', l):
                        cpp_match = True
        if cpp_match:
            dead_methods.append((header_path, mname, "有声明和实现，但全项目没有任何调用点 (疑似死函数)"))

print(f"=== 扫描到的私有方法总数: {len(class_private_methods)} ===")
print(f"=== 疑似死函数 / 未调用方法: {len(dead_methods)} 处 ===")
for p, mname, desc in dead_methods:
    print(f"  {p} -> {mname}(): {desc}")
EOF

