#!/usr/bin/env python3
"""
Dead Code and Redundancy Scanner for fcitx5-vinput.
Scans the codebase for:
- Dead private methods and member variables
- Uncalled static / internal helper functions
- Redundant return; statements
- Redundant boolean comparisons
- Redundant std::move on primitives
"""

import os
import re
import sys
from collections import defaultdict

def collect_source_files(root_dir="src"):
    sources = []
    headers = []
    for root, _, files in os.walk(root_dir):
        for f in files:
            full = os.path.join(root, f)
            if f.endswith(".h"):
                headers.append(full)
            elif f.endswith(".cpp"):
                sources.append(full)
    return headers, sources

def scan_dead_code():
    headers, sources = collect_source_files()
    all_files = headers + sources

    file_contents = {}
    full_corpus = ""
    for path in all_files:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            c = f.read()
            file_contents[path] = c
            full_corpus += "\n" + c

    issues = []

    # 1. Check unused private methods
    for h_path in headers:
        content = file_contents[h_path]
        private_blocks = re.findall(r'private:\s*(.*?)(?:public:|protected:|};)', content, re.DOTALL)
        for block in private_blocks:
            matches = re.finditer(r'(?:virtual\s+)?([a-zA-Z0-9_<>&*:]+)\s+([A-Z][a-zA-Z0-9_]*|[a-z][a-zA-Z0-9_]*)\s*\(([^)]*)\)\s*(?:const)?\s*(?:override)?\s*;', block)
            for mm in matches:
                mname = mm.group(2)
                if mname in ["Q_OBJECT", "Q_DISABLE_COPY", "override", "virtual"] or mname.startswith("~"):
                    continue
                tokens = re.findall(r'\b' + re.escape(mname) + r'\b', full_corpus)
                if len(tokens) <= 2:
                    issues.append({
                        "type": "dead_method",
                        "file": h_path,
                        "symbol": mname,
                        "msg": f"Private method '{mname}()' declared/defined but has 0 external/internal callers"
                    })

    # 2. Check redundant void return;
    for path in all_files:
        lines = file_contents[path].splitlines()
        for i in range(len(lines) - 1):
            if re.match(r'^\s*return\s*;\s*$', lines[i]) and re.match(r'^\s*}\s*$', lines[i+1]):
                if i > 0 and not re.search(r'\b(if|else|case|default|while|for)\b', lines[i-1]):
                    issues.append({
                        "type": "redundant_return",
                        "file": path,
                        "line": i + 1,
                        "symbol": "return;",
                        "msg": f"Redundant 'return;' at end of void block"
                    })

    # 3. Check redundant boolean comparisons
    for path in all_files:
        lines = file_contents[path].splitlines()
        for i, line in enumerate(lines):
            clean = line.strip()
            if not clean.startswith("//") and not clean.startswith("/*"):
                if re.search(r'==\s*(true|false)\b|!=\s*(true|false)\b', clean):
                    issues.append({
                        "type": "redundant_bool",
                        "file": path,
                        "line": i + 1,
                        "symbol": clean,
                        "msg": f"Redundant boolean comparison: {clean}"
                    })

    return issues

def main():
    print("==================================================")
    print(" fcitx5-vinput Dead Code & Redundancy Scanner")
    print("==================================================")
    issues = scan_dead_code()

    dead_methods = [i for i in issues if i["type"] == "dead_method"]
    redundant_returns = [i for i in issues if i["type"] == "redundant_return"]
    redundant_bools = [i for i in issues if i["type"] == "redundant_bool"]

    print(f"\n[+] Dead/Uncalled Methods: {len(dead_methods)}")
    for d in dead_methods:
        print(f"  - {d['file']}: {d['msg']}")

    print(f"\n[+] Redundant 'return;' statements: {len(redundant_returns)}")
    for r in redundant_returns[:10]:
        print(f"  - {r['file']}:{r['line']}: {r['msg']}")
    if len(redundant_returns) > 10:
        print(f"    ... and {len(redundant_returns) - 10} more")

    print(f"\n[+] Redundant Boolean comparisons: {len(redundant_bools)}")
    for b in redundant_bools:
        print(f"  - {b['file']}:{b['line']}: {b['msg']}")

    print("\n--------------------------------------------------")
    print(f"Summary: Total {len(issues)} issues detected.")
    print("--------------------------------------------------")

if __name__ == "__main__":
    main()

