static std::string StripTerminalEscapes(const std::string &s) {
  std::string out;
  out.reserve(s.size());
  for (size_t i = 0; i < s.size();) {
    if (s[i] == '\033') {
      if (i + 1 < s.size() && s[i + 1] == ']') {
        i += 2;
        while (i < s.size()) {
          if (s[i] == '\a') {
